CREATE TABLE IF NOT EXISTS products (id CHAR(36) PRIMARY KEY,seller_id CHAR(36) NOT NULL,title VARCHAR(150) NOT NULL,description LONGTEXT NOT NULL,tags JSON NOT NULL,seo_title VARCHAR(70) NULL,seo_description VARCHAR(170) NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',rejection_reason TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT products_seller_fk FOREIGN KEY (seller_id) REFERENCES sellers(id) ON DELETE CASCADE,INDEX products_seller_created_idx (seller_id,created_at),INDEX products_status_idx (status));
